/**
 * #1454 — loader for the path-claims golden fixtures under
 * `smoke-tests/fixtures/work-state/`, generated by
 * `extension/scripts/gen-claims-fixtures.ts`.
 *
 * Why fixtures rather than the inline `JSON.stringify` writes the test used to
 * make: the shape of a claims entry — and of the claimant's state file — is a
 * contract between the claims gate and the state schema. Inline literals
 * drift, and the observed #1421/#1427 park was exactly a shape nobody's test
 * carried. These files are what the gate is asserted against.
 *
 * Three placeholders keep the fixtures deterministic while still exercising
 * liveness against the real process table:
 *   - `"pid": -1`               → substituted with a pid the caller knows is
 *                                 alive (defaults to the test's own pid).
 *   - `"@AGE(-<ms>)"`           → `now - <ms>`, so "87 minutes ago" is a fact
 *                                 in the fixture rather than arithmetic in the
 *                                 test.
 *   - `"@WORKTREE(<name>)"`     → `<repoRoot>/.worktrees/<name>`, so a fixture
 *                                 resolves against whichever temp repo the test
 *                                 made instead of hardcoding a path.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { PathClaimEntry } from "../../../src/work-driver-path-claims.ts";
import type { WorkState } from "../../../src/workflow-state.ts";

const HERE = dirname(fileURLToPath(import.meta.url));
/** The directory these fixtures live in — `smoke-tests/fixtures/work-state`. */
export const FIXTURE_DIR = HERE;
export const CLAIMS_FIXTURE_DIR = join(HERE, "path-claims");

/** Sentinel pid in a fixture meaning "substitute a pid that is definitely alive". */
export const LIVE_PID_SENTINEL = -1;

/** The #1454 observed overlap: what #1421 claimed and what #1427 declared. */
export const CLAIMED_PATHS = [
  "extension/src/worktree-provision.ts",
  "extension/src/work-driver-verify-develop-helpers.ts",
];
export const OVERLAPPING_PATHS = ["extension/src/work-driver-verify-develop-helpers.ts"];

/** ~87 minutes — the age the #1421 claim carried when #1427 parked. */
export const OBSERVED_CLAIM_AGE_MS = 5_220_000;

type Json = string | number | boolean | null | Json[] | { [k: string]: Json };

function substitute(value: Json, livePid: number, now: number, repoRoot: string): Json {
  if (typeof value === "string") {
    const age = value.match(/^@AGE\((-?\d+)\)$/);
    if (age) return now + Number(age[1]);
    const wt = value.match(/^@WORKTREE\((.+)\)$/);
    if (wt) return join(repoRoot, ".worktrees", String(wt[1]));
    return value;
  }
  if (Array.isArray(value)) return value.map((v) => substitute(v, livePid, now, repoRoot));
  if (value !== null && typeof value === "object") {
    const out: { [k: string]: Json } = {};
    for (const [k, v] of Object.entries(value)) {
      if (k === "$comment") continue;
      out[k] =
        k === "pid" && v === LIVE_PID_SENTINEL ? livePid : substitute(v, livePid, now, repoRoot);
    }
    return out;
  }
  return value;
}

function read(path: string): Json {
  return JSON.parse(readFileSync(path, "utf8")) as Json;
}

/** Load a claims fixture, resolving its placeholders against `now` / `repoRoot`. */
export function loadFixtureClaims(
  name: string,
  opts: { livePid?: number; now?: number; repoRoot?: string } = {},
): PathClaimEntry[] {
  const livePid = opts.livePid ?? process.pid;
  const now = opts.now ?? Date.now();
  const repoRoot = opts.repoRoot ?? "/repo-root-unresolved";
  const raw = read(join(CLAIMS_FIXTURE_DIR, `${name}.json`));
  const claims = (raw as { claims?: Json[] }).claims ?? [];
  return substitute(claims, livePid, now, repoRoot) as unknown as PathClaimEntry[];
}

/** Load a work-state fixture (the claimant's own `.pi/work-state/<N>.json`). */
export function loadFixtureState(
  name: string,
  opts: { livePid?: number; now?: number; repoRoot?: string } = {},
): WorkState {
  const livePid = opts.livePid ?? process.pid;
  const now = opts.now ?? Date.now();
  const repoRoot = opts.repoRoot ?? "/repo-root-unresolved";
  return substitute(
    read(join(FIXTURE_DIR, `${name}.json`)),
    livePid,
    now,
    repoRoot,
  ) as unknown as WorkState;
}
